solution.solution.cpp:
#include <cstddef>

struct LIST_ENTRY { LIST_ENTRY* Flink; LIST_ENTRY* Blink; };

#define CONTAINING_RECORD(address, type, field) \
    reinterpret_cast<type*>(reinterpret_cast<char*>(address) - offsetof(type, field))

void InitializeListHead(LIST_ENTRY* head) { head->Flink = head->Blink = head; }
bool IsListEmpty(const LIST_ENTRY* head) { return head->Flink == head; }

void InsertHeadList(LIST_ENTRY* head, LIST_ENTRY* entry)
{
    LIST_ENTRY* first{ head->Flink };
    entry->Flink = first;
    entry->Blink = head;
    first->Blink = entry;
    head->Flink = entry;
}

void InsertTailList(LIST_ENTRY* head, LIST_ENTRY* entry)
{
    LIST_ENTRY* last{ head->Blink };
    entry->Flink = head;
    entry->Blink = last;
    last->Flink = entry;
    head->Blink = entry;
}

bool RemoveEntryList(LIST_ENTRY* entry)
{
    LIST_ENTRY* next{ entry->Flink };
    LIST_ENTRY* prev{ entry->Blink };
    prev->Flink = next;
    next->Blink = prev;
    return next == prev;
}

LIST_ENTRY* RemoveHeadList(LIST_ENTRY* head)
{
    LIST_ENTRY* entry{ head->Flink };
    if (entry != head) RemoveEntryList(entry);
    return entry;
}

LIST_ENTRY* RemoveTailList(LIST_ENTRY* head)
{
    LIST_ENTRY* entry{ head->Blink };
    if (entry != head) RemoveEntryList(entry);
    return entry;
}

int checkList(const LIST_ENTRY* head)
{
    int count{ 0 };
    const LIST_ENTRY* e{ head };
    for (int steps{ 0 }; steps <= 100000; ++steps)
    {
        if (!e->Flink || e->Flink->Blink != e) return -1;
        e = e->Flink;
        if (e == head) return count;
        ++count;
    }
    return -1;
}

unitTests:
#include <vector>
struct Item { int value; LIST_ENTRY link; };
std::vector<int> values(LIST_ENTRY* head) { std::vector<int> v; for (LIST_ENTRY* e = head->Flink; e != head; e = e->Flink) v.push_back(CONTAINING_RECORD(e, Item, link)->value); return v; }
TEST("empty") { LIST_ENTRY h; InitializeListHead(&h); CHECK(IsListEmpty(&h)); CHECK_EQ(checkList(&h), 0); CHECK(RemoveHeadList(&h) == &h); }
TEST("insert and walk") {
    LIST_ENTRY h; InitializeListHead(&h); Item a{ 1 }, b{ 2 }, c{ 3 };
    InsertTailList(&h, &a.link); InsertTailList(&h, &b.link); InsertHeadList(&h, &c.link);
    CHECK_EQ(values(&h), (std::vector<int>{ 3, 1, 2 })); CHECK_EQ(checkList(&h), 3); CHECK(!IsListEmpty(&h));
    CHECK(h.Flink == &c.link); CHECK(h.Blink == &b.link); CHECK(b.link.Flink == &h);
}
TEST("remove") {
    LIST_ENTRY h; InitializeListHead(&h); Item a{ 1 }, b{ 2 }, c{ 3 };
    InsertTailList(&h, &a.link); InsertTailList(&h, &b.link); InsertTailList(&h, &c.link);
    CHECK(!RemoveEntryList(&b.link)); CHECK_EQ(values(&h), (std::vector<int>{ 1, 3 }));
    CHECK_EQ(CONTAINING_RECORD(RemoveHeadList(&h), Item, link)->value, 1); CHECK_EQ(CONTAINING_RECORD(RemoveTailList(&h), Item, link)->value, 3);
    CHECK(IsListEmpty(&h)); CHECK_EQ(checkList(&h), 0);
    InsertTailList(&h, &a.link); CHECK(RemoveEntryList(&a.link)); CHECK(IsListEmpty(&h));
}
TEST("a broken list is detected") {
    LIST_ENTRY h; InitializeListHead(&h); Item a{ 1 }, b{ 2 }; InsertTailList(&h, &a.link); InsertTailList(&h, &b.link);
    b.link.Blink = &h; CHECK_EQ(checkList(&h), -1);
}

